def test_is_upper_shapes():
    for cls in classes:
        for rows, cols in ((0, 0), (0, 3), (3, 0), (1, 1), (1, 4),
                           (4, 1), (2, 4), (4, 2), (3, 3)):
            assert cls.zeros(rows, cols).is_upper is True
            a = cls(rows, cols, lambda i, j: int(i <= j))
            assert a.is_upper is True
            for i in range(rows):
                for j in range(cols):
                    b = zeros(rows, cols)
                    b[i, j] = 1
                    assert cls(b).is_upper is (i <= j)


